@pytest.mark.parametrize(
    "weird_id",
    ["0", "-1", "null", "x" * 1024, "%E6%BC%A2", "id%20with%20spaces"],
    ids=["zero", "negative", "literal_null", "very_long", "encoded_unicode", "encoded_spaces"],
)
def test_get_with_unusual_nonexistent_id_returns_404(api, base_url, weird_id):
    assert api.get(f"{base_url}/api/submissions/{weird_id}").status_code == 404


@pytest.mark.parametrize(
    "weird_id",
    ["0", "-1", "x" * 1024, "%E6%BC%A2"],
    ids=["zero", "negative", "very_long", "encoded_unicode"],
)
def test_delete_with_unusual_nonexistent_id_returns_404(api, base_url, weird_id):
    assert api.delete(f"{base_url}/api/submissions/{weird_id}").status_code == 404
